{
  "watches": [
    {
      "name": "todomvc-core",
      "targets": [
        "features/todomvc.feature:New todo input is focused on load",
        "features/todomvc.feature:No todos shows hidden main and footer",
        "features/todomvc.feature:Adding a new todo",
        "features/todomvc.feature:Empty input does not create a todo",
        "features/todomvc.feature:Adding multiple todos",
        "features/todomvc.feature:Completing a todo",
        "features/todomvc.feature:Toggle all marks all complete",
        "features/todomvc.feature:Toggle all unchecks when one item is incomplete",
        "features/todomvc.feature:Clear completed removes completed todos",
        "features/todomvc.feature:Clear completed hides button when no completed",
        "features/todomvc.feature:Destroy removes a todo",
        "features/todomvc.feature:Counter shows active count",
        "features/todomvc.feature:Counter uses plural for multiple items"
      ]
    },
    {
      "name": "todomvc-editing",
      "targets": [
        "features/todomvc.feature:Editing a todo on double-click",
        "features/todomvc.feature:Editing saves on Enter",
        "features/todomvc.feature:Editing saves on blur",
        "features/todomvc.feature:Editing discards on Escape",
        "features/todomvc.feature:Editing with empty value destroys the todo"
      ]
    },
    {
      "name": "todomvc-routing",
      "targets": [
        "features/todomvc.feature:Filter shows all todos by default",
        "features/todomvc.feature:Filter active shows only incomplete todos",
        "features/todomvc.feature:Filter completed shows only completed todos"
      ]
    },
    {
      "name": "todomvc-persistence",
      "targets": [
        "features/todomvc.feature:Persistence across page loads"
      ]
    }
  ]
}

(() => {
	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;
	var STORAGE_KEY = "todos-vanillajs";

	var todos = [];
	var editingId = null;
	var currentFilter = "all";

	// --- Storage ---

	function save() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function load() {
		var data;
		try {
			data = localStorage.getItem(STORAGE_KEY);
			if (data) {
				todos = JSON.parse(data);
			}
		} catch (_e) {
			todos = [];
		}
	}

	// --- Todo CRUD ---

	function createTodo(title) {
		var trimmed = title.trim();
		if (!trimmed) return null;
		var todo = {
			id: Date.now() + Math.random(),
			title: trimmed,
			completed: false,
		};
		todos.push(todo);
		save();
		return todo;
	}

	function destroyTodo(id) {
		todos = todos.filter((t) => t.id !== id);
		if (editingId === id) editingId = null;
		save();
	}

	function toggleTodo(id) {
		var todo = todos.find((t) => t.id === id);
		if (todo) {
			todo.completed = !todo.completed;
			save();
		}
	}

	function toggleAll() {
		var allCompleted = todos.length > 0 && todos.every((t) => t.completed);
		todos.forEach((t) => {
			t.completed = !allCompleted;
		});
		save();
	}

	function clearCompleted() {
		todos = todos.filter((t) => !t.completed);
		save();
	}

	function editTodo(id, newTitle) {
		var trimmed = newTitle.trim();
		if (!trimmed) {
			destroyTodo(id);
			return;
		}
		var todo = todos.find((t) => t.id === id);
		if (todo) {
			todo.title = trimmed;
			save();
		}
	}

	// --- Filtered view ---

	function getFilteredTodos() {
		if (currentFilter === "active") {
			return todos.filter((t) => !t.completed);
		}
		if (currentFilter === "completed") {
			return todos.filter((t) => t.completed);
		}
		return todos;
	}

	// --- DOM ---

	var newTodoInput = document.querySelector(".new-todo");
	var todoList = document.querySelector(".todo-list");
	var mainSection = document.querySelector(".main");
	var footer = document.querySelector(".footer");
	var toggleAllCheckbox = document.getElementById("toggle-all");
	var todoCount = document.querySelector(".todo-count");
	var clearCompletedBtn = document.querySelector(".clear-completed");
	var editEl = null;

	function render() {
		var filtered = getFilteredTodos();
		var activeCount = todos.filter((t) => !t.completed).length;
		var completedCount = todos.filter((t) => t.completed).length;

		// Show/hide main and footer
		if (todos.length === 0) {
			mainSection.style.display = "none";
			footer.style.display = "none";
		} else {
			mainSection.style.display = "";
			footer.style.display = "";
		}

		// Render todo list
		todoList.innerHTML = "";
		filtered.forEach((todo) => {
			var li = document.createElement("li");
			li.dataset.id = todo.id;

			if (todo.completed) li.classList.add("completed");
			if (editingId === todo.id) li.classList.add("editing");

			var viewDiv = document.createElement("div");
			viewDiv.className = "view";

			var toggle = document.createElement("input");
			toggle.className = "toggle";
			toggle.type = "checkbox";
			if (todo.completed) toggle.checked = true;

			var label = document.createElement("label");
			label.textContent = todo.title;

			var destroyBtn = document.createElement("button");
			destroyBtn.className = "destroy";

			viewDiv.appendChild(toggle);
			viewDiv.appendChild(label);
			viewDiv.appendChild(destroyBtn);

			var editInput = document.createElement("input");
			editInput.className = "edit";
			editInput.value = todo.title;

			li.appendChild(viewDiv);
			li.appendChild(editInput);
			todoList.appendChild(li);
		});

		// Counter
		todoCount.innerHTML =
			"<strong>" +
			activeCount +
			"</strong> " +
			(activeCount === 1 ? "item" : "items") +
			" left";

		// Clear completed button visibility
		if (completedCount === 0) {
			clearCompletedBtn.style.display = "none";
		} else {
			clearCompletedBtn.style.display = "";
		}

		// Toggle-all state
		toggleAllCheckbox.checked =
			todos.length > 0 && todos.every((t) => t.completed);

		// Filter links
		var filterLinks = document.querySelectorAll(".filters a");
		filterLinks.forEach((link) => {
			link.classList.remove("selected");
			if (
				link.getAttribute("href") ===
				`#/${currentFilter === "all" ? "" : currentFilter}`
			) {
				link.classList.add("selected");
			}
		});

		// Focus editing input if editing
		if (editingId !== null) {
			editEl = todoList.querySelector("li.editing .edit");
			if (editEl) {
				editEl.focus();
				editEl.selectionStart = editEl.value.length;
			}
		}
	}

	// --- Event handlers ---

	newTodoInput.addEventListener("keydown", (e) => {
		var t;
		if (e.keyCode === ENTER_KEY) {
			t = newTodoInput.value.trim();
			if (t) {
				createTodo(t);
				newTodoInput.value = "";
				render();
			}
		}
	});

	todoList.addEventListener("click", (e) => {
		var target = e.target;
		var li = target.closest("li");
		if (!li) return;
		var id = Number(li.dataset.id);

		if (target.classList.contains("toggle")) {
			toggleTodo(id);
			render();
		} else if (target.classList.contains("destroy")) {
			destroyTodo(id);
			render();
		}
	});

	todoList.addEventListener("dblclick", (e) => {
		if (e.target.tagName !== "LABEL") return;
		var li = e.target.closest("li");
		if (!li) return;
		editingId = Number(li.dataset.id);
		render();
	});

	todoList.addEventListener(
		"blur",
		(e) => {
			if (!e.target.classList.contains("edit")) return;
			var li = e.target.closest("li");
			if (!li) return;
			var id = Number(li.dataset.id);
			if (editingId === id) {
				editTodo(id, e.target.value);
				editingId = null;
				render();
			}
		},
		true,
	);

	todoList.addEventListener("keydown", (e) => {
		if (!e.target.classList.contains("edit")) return;
		var li = e.target.closest("li");
		if (!li) return;

		if (e.keyCode === ENTER_KEY) {
			e.target.blur();
		} else if (e.keyCode === ESCAPE_KEY) {
			editingId = null;
			render();
		}
	});

	toggleAllCheckbox.addEventListener("change", () => {
		toggleAll();
		render();
	});

	clearCompletedBtn.addEventListener("click", () => {
		clearCompleted();
		render();
	});

	document.querySelector(".filters").addEventListener("click", (e) => {
		var link = e.target.closest("a");
		if (!link) return;
		var href = link.getAttribute("href");
		if (href === "#/") {
			currentFilter = "all";
		} else if (href === "#/active") {
			currentFilter = "active";
		} else if (href === "#/completed") {
			currentFilter = "completed";
		}
		render();
	});

	// --- Routing ---

	function handleRoute() {
		var hash = window.location.hash || "#/";
		if (hash === "#/active") {
			currentFilter = "active";
		} else if (hash === "#/completed") {
			currentFilter = "completed";
		} else {
			currentFilter = "all";
		}
		render();
	}

	window.addEventListener("hashchange", handleRoute);

	// --- Init ---

	load();
	handleRoute();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// --- Given ---

Given('the app is loaded', function () {
  // app is loaded by world.js Before hook
});

// --- When ---

When('I type {string} and press Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

When('I toggle the todo at index {int}', function (index) {
  const toggles = this.document.querySelectorAll('.todo-list .toggle');
  toggles[index].click();
});

When('I click toggle all', function () {
  const checkbox = this.document.getElementById('toggle-all');
  checkbox.checked = !checkbox.checked;
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click clear completed', function () {
  this.document.querySelector('.clear-completed').click();
});

When('I destroy the todo at index {int}', function (index) {
  const destroys = this.document.querySelectorAll('.todo-list .destroy');
  destroys[index].click();
});

When('I double-click the label at index {int}', function (index) {
  const labels = this.document.querySelectorAll('.todo-list label');
  labels[index].dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('I clear the edit input and type {string} and press Enter', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

When('I clear the edit input and type {string} and blur', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I clear the edit input and type {string} and press Escape', function (text) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = text;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 27, key: 'Escape', bubbles: true }));
});

When('I clear the edit input and press Enter', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, key: 'Enter', bubbles: true }));
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('the page is reloaded', function () {
  // Capture current localStorage state before destroying the window
  const stored = this.window.localStorage.getItem('todos-vanillajs');
  // Dispose old window
  const oldWindow = this.window;
  this.window = undefined;
  this.document = undefined;
  // Create a fresh window and pre-populate localStorage before app init
  const { Window } = require('happy-dom');
  const fs = require('fs');
  const path = require('path');
  const ROOT = path.resolve(__dirname, '..', '..');
  this.window = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  this.document = this.window.document;
  // Pre-populate localStorage BEFORE app loads
  if (stored) {
    this.window.localStorage.setItem('todos-vanillajs', stored);
  }
  // Load the page and app
  this.document.write(fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8'));
  this.document.close();
  this.window.eval(fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8'));
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));
  // Dispose old window
  if (oldWindow && oldWindow.happyDOM && typeof oldWindow.happyDOM.close === 'function') {
    oldWindow.happyDOM.close();
  }
});

// --- Then ---

Then('the new todo input should be focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(this.document.activeElement, input);
});

Then('the main section should be hidden', function () {
  const main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none');
});

Then('the footer should be hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none');
});

Then('there should be {int} todo item(s)', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count);
});

Then('there should be {int} visible todo items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count);
});

Then('the todo at index {int} should have title {string} and be completed', function (index, title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[index];
  const label = li.querySelector('label');
  const toggle = li.querySelector('.toggle');
  assert.strictEqual(label.textContent, title);
  assert.strictEqual(toggle.checked, true);
  assert(li.classList.contains('completed'));
});

Then('the todo at index {int} should have title {string} and not be completed', function (index, title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[index];
  const label = li.querySelector('label');
  const toggle = li.querySelector('.toggle');
  assert.strictEqual(label.textContent, title);
  assert.strictEqual(toggle.checked, false);
  assert(!li.classList.contains('completed'));
});

Then('the todo at index {int} should have title {string}', function (index, title) {
  const items = this.document.querySelectorAll('.todo-list li');
  const label = items[index].querySelector('label');
  assert.strictEqual(label.textContent, title);
});

Then('the todo at index {int} should be completed', function (index) {
  const items = this.document.querySelectorAll('.todo-list li');
  const toggle = items[index].querySelector('.toggle');
  assert.strictEqual(toggle.checked, true);
});

Then('the toggle all checkbox should be checked', function () {
  const checkbox = this.document.getElementById('toggle-all');
  assert.strictEqual(checkbox.checked, true);
});

Then('the toggle all checkbox should not be checked', function () {
  const checkbox = this.document.getElementById('toggle-all');
  assert.strictEqual(checkbox.checked, false);
});

Then('the clear completed button should be hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.strictEqual(btn.style.display, 'none');
});

Then('the counter should show {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.strictEqual(counter.textContent, text);
});

Then('the todo at index {int} should be in editing mode', function (index) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[index];
  assert(li.classList.contains('editing'));
});

Then('the input should be empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

